head.script:
scwin.trigger1_onclick = function(e) {
    var json = [{
            col1: 'Name1',
            col2: 'Value1',
            col3: 'Option1'
        },
        {
            col1: 'Name2',
            col2: 'Value2',
            col3: 'Option2'
        },
        {
            col1: 'Name3',
            col2: 'Value3',
            col3: 'Option3'
        }
    ];
    dataList1.setJSON(json);
};
scwin.gridView1_oncontextopen = function(row, col) {
    // return false; // 컨텍스트 메뉴를 보여주지 않습니다.
    // return { hideSystemMenu: false } // 전체 시스템 메뉴를 보여주지 않습니다.
    return {
        hideSystemMenu: ["ColumnHide"], // 특정 항목의 시스템 메뉴를 보여주지 않습니다.
        appendMenu: [{
            label: "특별한 컬럼 숨기기",
            // 사용자 메뉴의 표시 문자열
            userMenuId: "userColumnHide",
            // 사용자 메뉴의 id, 해당 컨텍스트 메뉴가 클릭될때, 입력값으로 전달됨
            className: "userMenu"
            // 사용자 메뉴의 스타일 클래스 이름 
        }] // 시스템 메뉴 아래에, 사용자 메뉴를 추가합니다.
    };
};
scwin.gridView1_oncontextclick = function(row, col, userMenuId, isSystemMenu, systemMenu) {
    if (isSystemMenu) {
        alert(systemMenu + " clicked at (" + col + "," + row + ")!");
    } else {
        alert(userMenuId + " clicked at (" + col + "," + row + ")!");
    }
};
scwin.__triggerMouse = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('oncontextmenu');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('contextmenu', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.oncontextmenu == 'function') {
        node.oncontextmenu();
    }
}
scwin.__isShowContextMenu = function() {
    var rows = WebSquare.wUnit.getJq("#gridView1_contextMenu_list").find(".w2list_listRow");
    return rows.length == 6;
}
scwin.__notErrorLog = function() {
    var err = WebSquare.logger.getErrorLog();
    return (err != "") ? true : false;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 gridView header영역에 마우스 우클릭을 실행하여 contextMenu가 나오는지를 확인하고 마우스 우클릭 로그보기도 확인한다.
    //1. Execute the sample file and right-click on the gridView header area to check if the contextMenu is displayed. Also, check the right-click log view.
    WebSquare.wUnit.addCommand("set", "scwin.__triggerMouse('gridView1_column9')");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. contextMenu(5가지)가 정상적으로 동작되어 보여지고 로그도 오류없이 정상적으로 보여진다.
    //1. ContextMenu (5 kinds) is displayed normally and logs are displayed normally without errors.
   WebSquare.wUnit.addCommand("assert", "scwin.__isShowContextMenu()", "true");
    WebSquare.wUnit.addCommand("pause", "500");   
    WebSquare.wUnit.addCommand("assert", "scwin.__notErrorLog()", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

